-- ============================================================
-- MIGRACIÓN: Tablas clientes + productos para app vendedores
-- Columnas alineadas con codigo.gs (GAS trigger cada 10 min)
-- Ejecutar en: Supabase Dashboard → SQL Editor
-- ============================================================

-- PASO 1: Crear tabla clientes (estructura idéntica a lo que envía GAS)
CREATE TABLE IF NOT EXISTS clientes (
  id          TEXT PRIMARY KEY,
  nombre      TEXT,
  apellido    TEXT,
  domicilio   TEXT,
  localidad   TEXT,
  lat         TEXT,
  lng         TEXT,
  vendedor    TEXT,
  activo      BOOLEAN DEFAULT true,
  updated_at  TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_clientes_vendedor ON clientes(vendedor);
CREATE INDEX IF NOT EXISTS idx_clientes_activo   ON clientes(activo);
CREATE INDEX IF NOT EXISTS idx_clientes_updated  ON clientes(updated_at DESC);
ALTER TABLE clientes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS public_all_clientes ON clientes;
CREATE POLICY public_all_clientes ON clientes FOR ALL USING (true) WITH CHECK (true);

-- PASO 2: Crear tabla productos
CREATE TABLE IF NOT EXISTS productos (
  id          uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  nombre      TEXT NOT NULL,
  marca       TEXT,
  precio      NUMERIC,
  keywords    TEXT,
  activo      BOOLEAN DEFAULT true,
  updated_at  TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_productos_activo  ON productos(activo);
CREATE INDEX IF NOT EXISTS idx_productos_marca   ON productos(marca);
CREATE INDEX IF NOT EXISTS idx_productos_updated ON productos(updated_at DESC);
ALTER TABLE productos ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS public_all_productos ON productos;
CREATE POLICY public_all_productos ON productos FOR ALL USING (true) WITH CHECK (true);

-- PASO 3: Importar 408 clientes del CSV
